update 
REP_ASSET_DEPT
set 
REP_SEND_STATUS = #{YES_OR_NO_Y}
where
REP_FINPROD_ID = #{finprodId}

mapper.select:
SELECT SUM(TDY_INTINCEXP) FROM ( SELECT TDY_INTINCEXP FROM PTL_SEC_VALUTION
CDATE = to_date(#{carryDate},'yyyy-mm-dd') AND Inv_Aim = '999999'
and portfolio_id = #{portfolioId}
and finprod_id = #{finprodId}
and sec_acct_id = #{secAcctId}
UNION ALL
SELECT SUM(SHARE_AMT*-1) TDY_INTINCEXP FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE PS='T12' AND FINPROD_ID=#{finprodId} AND TRADE_STATUS='01' AND IS_CANCEL='N' AND SETTLE_DATE=to_date(#{tradeDate},'yyyy-mm-dd')
and CHL_ID = #{secAcctId}
and CHL_ID IS NULL
)

select count(*) from TRD_PRODUCT_DEAL


    and B_TRADE_ID = #{bTradeId}


    and IS_CANCEL != #{yes}


    and TRADE_STATUS=#{tradeStatus}

select count(*) from WFL_TRD_PRODUCT_DEAL


    and B_TRADE_ID = #{bTradeId}


    and IS_CANCEL != #{yes}


    and TRADE_STATUS=#{tradeStatus}


    and PS != #{ps}

select deal.TRADE_ID from TRD_PRODUCT_DEAL deal
INNER JOIN FIN_PRODUCT_ADD T3
    ON deal.FINPROD_ID = T3.FINPROD_ID
    AND T3.TRM_FUND_TYPE = #{TRM_FUND_TYPE05}

    deal.B_TRADE_ID = #{bTradeId}
    AND deal.IS_CANCEL != #{yes}
    AND deal.TRADE_STATUS=#{tradeStatus}

UNION
select deal2.TRADE_ID from TRD_PRODUCT_DEAL deal
INNER JOIN FIN_PRODUCT_ADD T3
    ON deal.FINPROD_ID = T3.FINPROD_ID
    AND T3.TRM_FUND_TYPE = #{TRM_FUND_TYPE05}
INNER JOIN TRD_PRODUCT_DEAL deal2
    ON deal2.B_TRADE_ID = deal.TRADE_ID
    AND deal2.IS_CANCEL != #{yes}
    AND deal2.TRADE_STATUS=#{tradeStatus}

    deal.B_TRADE_ID = #{bTradeId}
    AND deal.IS_CANCEL != #{yes}
    AND deal.TRADE_STATUS=#{tradeStatus}

select count(*) from WFL_TRD_PRODUCT_DEAL
where 
B_TRADE_ID = #{bTradeId}

SELECT 
    TRADE_ID tradId,
    '0'     workflowId
FROM
    WFL_TRD_PRODUCT_DEAL

    B_TRADE_ID = #{tradId}
    /*modify by caojin 基金多组合交易存TOTLE_TRADE_ID，注释掉 20200810  start   */
    /*AND TOTLE_TRADE_ID IS NULL*/ 
    /*modify by caojin 基金多组合交易存TOTLE_TRADE_ID，注释掉 20200810  end   */

SELECT
    TRADE_ID tradId,
    '1'     workflowId
FROM
    TRD_PRODUCT_DEAL

    B_TRADE_ID = #{tradeId}
    /*modify by caojin 此处查询取得是赎回到账的TRADE_ID，基金多组合赎回到账   非通道交易在TRD_PRODUCT_DEAL不存TOTLE_TRADE_ID，
       通道交易存TOTLE_TRADE_ID，且存的是多组合赎回交易的TOTLE_TRADE_ID 20200814  start   */
    AND (TOTLE_TRADE_ID IS NULL 

        or TOTLE_TRADE_ID = #{totleTradeId}
    )
    /*modify by caojin  20200814  end   */

    AND IS_CANCEL = #{N}

SELECT NVL(T1.ENTRUST_AMT,'-1') entrustAmt, NVL(T1.ENTRUST_NUM,0) entrustNum, NVL(T2.FINISH_AMT,0) finishAmt, NVL(T5.PRIN_AMT,0) prinAmt FROM ETR_ENTRUST T1 LEFT JOIN ( SELECT FINISH_AMT, ENTRUST_ID FROM ETR_FINISH_STATUS
ENTRUST_ID = #{entrustId}
) T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN ( SELECT T4.PRIN_AMT,T3.ENTRUST_ID FROM WFL_TRD_PRODUCT_DEAL_ADD T3 LEFT JOIN WFL_TRD_PRODUCT_DEAL T4 ON T3.TRADE_ID = T4.TRADE_ID
T3.ENTRUST_ID = #{entrustId} AND T4.PS IN (#{pssg},#{pssh})
AND T4.TRADE_ID <> #{tradeId}
) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID
T1.ENTRUST_ID = #{entrustId}

SELECT T1.COUNTER_ID id, T1.COUNTER_NAME text FROM MST_COUNTER_PARTY T1
( T1.COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR T1.COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND T1.COUNTER_ID = #{initValue}
AND T1.COUNTER_TYPE = #{counterType}

select 

from WFL_STL_PAY_ORDERS
where TRADE_ID = #{tradId,jdbcType=VARCHAR}
